const CHATSEENKEY='hakoniwa-chat-v1';let CHATSEEN=null;/* 出た雑談は、ステージをこえておぼえる（ほかのステージで出た話は出にくい） */
function chatSeen(){if(!CHATSEEN){try{CHATSEEN=new Set(JSON.parse(KV.getItem(CHATSEENKEY)||'[]'))}catch(e){CHATSEEN=new Set()}}return CHATSEEN}
function chatMark(i){const C=chatSeen();if(C.has(i))return;C.add(i);try{KV.setItem(CHATSEENKEY,JSON.stringify([...C]))}catch(e){}}
function chatTopic(r,p){const L=[],mt=bondOf(r,p)>=BOND_TALK,gn=!!goneTalkName();CHATS.forEach((c,i)=>{if((c.st==null||c.st===WD)&&(!c.el||c.el===r.elem)&&(!c.pk||c.pk===elemKey(r))&&(!c.ok||c.ok(r,p))&&(!c.key||isKey(r.name)&&isKey(p.name))&&(!c.mate||mt)&&(!c.gone||gn)&&(!c.kc||kcOK(c,r,p)))L.push(i)});/* なかよし同士だと、なかよしの話もまざる *//* 話しかけた子の属性のお話もまざる */
  {const hs=L.filter(i=>CHATS[i].hint),nh=L.filter(i=>!CHATS[i].hint),use=hs.length&&(Math.random()<.25||!nh.length)?hs:nh;if(use.length)L.splice(0,L.length,...use)}/* スポットのヒントは、たまに（4回に1回くらい） */
  if(gn&&Math.random()<.5){const F=L.filter(i=>CHATS[i].gone);if(F.length)L.splice(0,L.length,...F)}/* 消えたばかりの子がいる日は、その子の話が出やすい */
  if(festOn()){const F=L.filter(i=>CHATS[i].fest);if(F.length)L.splice(0,L.length,...F)}/* おまつりの日は、おまつりの話だけ */
  const R=S.chatRec||(S.chatRec=[]),G=chatSeen(),last=i=>{const k=R.lastIndexOf(i);return k>=0?k:G.has(i)?-.5:-1}/* まだどこでも出ていない話 → ほかのステージで出た話 → このステージで前に出た話 */,lo=Math.min(...L.map(last));let C=L.filter(i=>last(i)===lo);/* だれとだれの会話でも、まだしていない話（なければ、いちばん前にした話）からえらぶ。ひととおりするまで、同じ話はしない */
  if(C.some(i=>CHATS[i].kc)&&Math.random()<.4)C=C.filter(i=>CHATS[i].kc);/* キーキャラの話は、まだしていなければ4割で選ばれる */
  const t=C[Math.floor(Math.random()*C.length)];for(let o;(o=R.indexOf(t))>=0;)R.splice(o,1);R.push(t);chatMark(t);return t}
/* 「手、ふっとこうか」：このあと手をふる */
function trySocial(r,G){const sb=socialBest(r,G);if(!sb)return false;const best=sb.b;const o=S.res.find(q=>q.id===best.o.partner);if(!o)return false;endAct(o);o.act={type:'chatwait',stage:'do',t:0,partner:r.id};o.bubble='👋';startAct(r,G,'chat',best.stand,best.o);return true}
const NIGATE={fire:['fountain'],wood:['campfire'],water:['campfire'],earth:['swing'],wind:[]};/* 属性ごとの、にがてなおもちゃ：遊びに行かない */
const nigate=(el,k)=>(NIGATE[el]||[]).includes(k);
const FAVTOY={earth:['sandbox'],wood:['swing'],water:['fountain'],fire:['campfire'],wind:['slide','seesaw','sandbox','swing','fountain','campfire']};/* 属性ごとに、よく遊ぶおもちゃ（ほかの子より選ばれやすい） */
const FISHP=.125,FISHPS=.2,FISHPA=.1;/* つりに行く確率：ふつうの水べ12.5%、つり場（水べのいす）20%、つりスポット・よるづり場は1つで+10% */
function goPlay(r,G,strict){
  const fq=Math.random()/((r.elem==='water'?2:1)*(r.like==='fish'?1.5:1)),allowFishing=fq<FISHPS+FISHPA*2;/* つりの割合：ふつうの子は1日1回くらい、水のせいれいは2回くらい（えらぶ点数が高い）、つり好きはもっと。つり場では、行く確率が上がる */let best=null,bs=-1e9;
  for(let j=0;j<W*H;j++){const d=G.dist[j];if(d<0||d>45)continue;const o=S.obj[j];
    if(o==='swing'&&free('o'+j,BL[o].play.cap)&&!toyTired(r,j)&&useFor(j,r)&&!nigate(r.elem,o)){/* 花では遊ばない */const p=BL[o].play;const s=p.pt*3+(r.like===o?6:0)+((FAVTOY[r.elem]||[]).includes(o)?7:0)+spotN(j,'park','park2')*4-d*.3+Math.random()*2;if(s>bs){bs=s;best={type:'play',stand:j,o:{key:'o'+j,obj:j,what:o,fun:p.fun,dur:p.dur,pt:p.pt,pw:p.pw}}}}
    const fk0=adjOf(j,k=>{const t=typeAt(k),p=t&&BL[t]&&BL[t].play;return !!(p&&p.adj&&free('o'+anc(k),p.cap)&&!toyTired(r,anc(k))&&!nigate(r.elem,t)&&useFor(k,r))}),fk=fk0>=0?anc(fk0):-1;
    if(fk>=0){const w=S.obj[fk],p=BL[w].play;const s=p.pt*3+(r.like===w?6:0)+((FAVTOY[r.elem]||[]).includes(w)?7:0)+spotN(fk,'park','park2')*4-d*.3+Math.random()*2;if(s>bs){bs=s;best={type:'play',stand:j,o:{key:'o'+fk,obj:fk,what:w,fun:p.fun,dur:p.dur,pt:p.pt,pw:p.pw}}}}
    if(allowFishing&&canJob(r,'fish')&&roomN(r)>0&&S.ground[j]!==1&&fishW(j)>=0&&free('f'+j,1)&&fq<(fSpot(j)?FISHPS+FISHPA*spotN(j,'fishspot','yoruzuri'):FISHP)){const sp=fSpot(j),s=10+(sp?12:0)+(r.like==='fish'?6:0)+(r.elem==='water'?9:0)-d*.3+Math.random()*2;if(s>bs){bs=s;best={type:'fish',stand:j,o:{key:'f'+j,spot:sp}}}}
  }
  {const sb=socialBest(r,G);if(sb&&sb.s>bs){bs=sb.s;best=sb.b}}
  if(!best)return strict?false:goWander(r,G);
  if(best.type==='chat'){const o=S.res.find(q=>q.id===best.o.partner);if(o){endAct(o);o.act={type:'chatwait',stage:'do',t:0,partner:r.id};o.bubble='👋'}}
  startAct(r,G,best.type,best.stand,best.o);if(best.type==='play')bondInvite(r,best.o);return true
}
const SPEC={wood:['plant','tend','fert','cookS'],water:['water','cookS'],fire:['cookS'],earth:['repair','till','cookS'],wind:['seed']};/* cookS：その属性の料理 *//* 草・きのこ・枝は、どの属性も木・石と同じ優先度でひろう *//* 属性ごとの得意な仕事：建てる・家具づくりのつぎに、ほかの仕事より先にする */
/* 得意な仕事は、その属性の子だけ。建てるのはみんなできる */
const OWN={plant:'wood',tend:'wood',water:'water',till:'earth',repair:'earth',seed:'wind'};/* 料理は、だれでもできる */
function ownOK(r,el){return !el||r.elem===el}
function canJob(r,k){if(k==='seed')return r.elem==='wind';if(k==='fert')return r.elem==='wood';if(k==='harvest'&&r.elem!=='wood'&&S.res.some(q=>q.elem==='wood'))return false;/* 収穫は、木のせいれいがいれば木のせいれい */if(k==='tend'&&S.res.some(q=>q.elem==='water'))return false;/* 水やりは、水のせいれいがいれば水のせいれい（木の子の世話の水やりはしない） *//* 外にふしぎな種があれば、風の子はみんな拾いに行く */return ownOK(r,OWN[k])}
const makerOf=id=>WD===1&&(id==='bench'||id==='noren')||id==='stor'||id==='mbox'||id==='crate'?null:BL[id].maker;/* 箱は、だれでも作れる *//* 火山のふもと：温泉のクエストに使うベンチ・のれんは、だれでも作れる */
function craftOK(r,o){return ownOK(r,makerOf(o.type))}
